def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    try:
        # Try to access standard Point attributes
        coords = {'x': getattr(value, 'x'), 'y': getattr(value, 'y')}
    except AttributeError:
        raise TypeError("Provided value does not have 'x' and 'y' attributes required for a Point")

    # Include z coordinate if present
    if hasattr(value, 'z'):
        coords['z'] = getattr(value, 'z')
    return coords

