def values(self, *keys):
        """ Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        # If no keys are supplied, return all values
        if not keys:
            return list(self.values())

        # Retrieve all values once for index-based access
        all_vals = list(self.values())
        result = []

        for k in keys:
            # Treat integer keys as indices
            if isinstance(k, int):
                try:
                    result.append(all_vals[k])
                except IndexError:
                    raise IndexError(f"Index {k} out of range.")
            else:
                # Treat non-integer keys as dictionary keys
                if k in self:
                    result.append(self[k])
                else:
                    raise KeyError(f"Key {k!r} not found in record.")
        return result

