def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Define the constructor for the new Point subclass.
    def __init__(self, x, y, **kwargs):
        # Basic validation: require exactly two coordinates.
        if not isinstance(x, (int, float)) or not isinstance(y, (int, float)):
            raise TypeError("x and y must be numeric values")
        self.x = x
        self.y = y
        # Set any provided keyword arguments as attributes, overriding defaults.
        for key, value in kwargs.items():
            setattr(self, key, value)

    # Prepare the dictionary of attributes for the new class.
    attrs = {
        "__init__": __init__,
        # Representations make debugging and introspection easier.
        "__repr__": lambda self: f"{name}({self.x}, {self.y})",
        "__str__": lambda self: f"{self.x}, {self.y}",
        # Store srid mapping so that external code can access it.
        "srid_map": srid_map or {},
    }

    # Add default field values provided via the `fields` dictionary.
    for field_name, default_value in fields.items():
        attrs[field_name] = default_value

    # Create the dynamic subclass using the built‑in `type` function.
    return type(name, (object,), attrs)

