def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not s:
        return ()
    parts = s.strip().split('.')
    nums = []
    for part in parts:
        digits = ''.join(c for c in part if c.isdigit())
        if digits:
            nums.append(int(digits))
    return tuple(nums)

