def mru_cache(maxsize=128, typed=False):
    def decorating_function(user_function):
        cache = {}
        order = []  # most recent first

        def make_key(args, kw):
            key = args
            if kw:
                for item in sorted(kw.items()):
                    key += item
            if typed:
                key = tuple((type(v), v) for v in key)
            return key

        def wrapper(*args, **kw):
            key = make_key(args, kw)
            if key in cache:
                value = cache[key]
                # Move to front (most recent)
                if key in order:
                    order.remove(key)
                order.insert(0, key)
                return value
            result = user_function(*args, **kw)
            cache[key] = result
            # Insert new key as most recent
            order.insert(0, key)
            # Evict most recent if size exceeded
            if len(order) > maxsize:
                evict_key = order.pop(0)
                cache.pop(evict_key, None)
            return result

        wrapper.cache_info = lambda: len(cache)
        return wrapper
    return decorating_function

