def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        counter = 0

        def _make_key(args, kwargs):
            if typed:
                key = []
                for arg in args:
                    key.append((arg, type(arg)))
                for k in sorted(kwargs):
                    key.append((k, kwargs[k], type(kwargs[k])))
                return tuple(key)
            else:
                return (args, tuple(sorted(kwargs)))

        def wrapper(*args, **kwargs):
            nonlocal counter
            key = _make_key(args, kwargs)
            if key in cache:
                val, freq, insert = cache[key]
                cache[key] = (val, freq + 1, insert)
                return val
            result = func(*args, **kwargs)
            if maxsize <= 0:
                return result
            counter += 1
            insertion = counter
            cache[key] = (result, 1, insertion)
            if len(cache) > maxsize:
                # Evict key with lowest frequency; if tie, oldest insertion
                min_freq = min(v[1] for v in cache.values())
                candidate_keys = [k for k, v in cache.items() if v[1] == min_freq]
                evict_key = min(candidate_keys, key=lambda k: cache[k][2])
                del cache[evict_key]
            return result

        return wrapper

    return decorator

