def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string, showing its type,
    message, and an excerpt of its traceback up to ``max_level`` frames.
    Filenames in the stack trace are shortened to at most
    ``max_path_level`` path components, preserving the file name
    and a few of the last directories.
    """
    import traceback
    import os

    def shrink_path(path, max_parts):
        """Return a path shortened to at most max_parts components."""
        parts = []
        # Normalize and split the path
        for part in os.path.normpath(path).split(os.sep):
            if part:
                parts.append(part)
        if len(parts) <= max_parts:
            return os.path.join(*parts)
        # Retain the last max_parts components
        return os.path.join(*parts[-max_parts:])

    messages = []
    depth = 0
    exc = e
    while exc is not None and depth < max_level:
        # Basic description
        messages.append(f"{type(exc).__name__}: {exc}")

        # Traceback extraction
        tb = exc.__traceback__
        if tb is not None:
            stack = traceback.extract_tb(tb)
            if stack:
                messages.append("Stack trace (most recent call last):")
                # Show at most max_level frames
                start = max(0, len(stack) - max_level)
                for frame in stack[start:]:
                    filename = shrink_path(frame.filename, max_path_level)
                    messages.append(f'  File "{filename}", line {frame.lineno}, in {frame.name}')
                    if frame.line:
                        messages.append(f"    {frame.line.strip()}")
                    else:
                        messages.append("    ")

        # Prepare for next exception in chain
        if exc.__cause__ is not None:
            exc = exc.__cause__
        elif exc.__context__ is not None:
            exc = exc.__context__
        else:
            break

        depth += 1
        if depth < max_level:
            messages.append("---")

    return "\n".join(messages)

