def _getTargetClass(self):
    """Return the implementation name in use, without the 'Py' or 'Fallback' suffix."""
    cls_name = type(self).__name__
    for suffix in ('Py', 'Fallback'):
        if cls_name.endswith(suffix):
            return cls_name[:-len(suffix)]
    return cls_name

