def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    for c in classes:
        redundant = False
        to_remove = []
        for d in result:
            if issubclass(c, d):
                to_remove.append(d)
            elif issubclass(d, c):
                redundant = True
                break
        if redundant:
            continue
        for d in to_remove:
            result.remove(d)
        result.append(c)
    return result

