def _update_context(self, context):
    # Determine coordinate names (first up to three non-error fields)
    field_names = getattr(self, "_fieldnames", [])
    coords = [name for name in field_names if not name.startswith("error_")][:3]
    # Map coordinates to "x", "y", "z"
    coord_map = {}
    for i, coord in enumerate(coords):
        if i < 3:
            coord_map[coord] = ["x", "y", "z"][i]
    # Access or create the error sub-dictionary
    if hasattr(context, "error"):
        err_sub = context.error
    else:
        err_sub = context.setdefault("error", {})
    # Iterate over error fields
    for idx, name in enumerate(field_names):
        if name.startswith("error_"):
            rest = name[6:]                     # remove "error_"
            # Find which coordinate the rest starts with
            for coord, prefix in coord_map.items():
                if rest.startswith(coord):
                    suffix = rest[len(coord):]   # e.g. "_low"
                    err_name = prefix + suffix  # e.g. "x_low"
                    # Append index for this error
                    err_sub.setdefault(err_name, {})["index"] = idx
                    break
    # No need to modify context.value – existing entries remain untouched
    return None

