def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Avoid treating strings or bytes as sequences of elements
    if isinstance(seq, (str, bytes)):
        return False

    # If seq itself is a FillRequest, return True immediately
    if isinstance(seq, FillRequest):
        return True

    # Do not consider Source sequences as valid FillRequest sequences
    if isinstance(seq, Source):
        return False

    # If seq is an iterable (but not a string/bytes), check for any FillRequest elements
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    for element in iterator:
        if isinstance(element, FillRequest):
            return True

    # No FillRequest elements found
    return False

