def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1, if a key is present both in *d1* and *d2*
    but has different values, it is included into the difference.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    def _deepcopy(obj):
        if isinstance(obj, dict):
            return {k: _deepcopy(v) for k, v in obj.items()}
        return obj

    def _diff(a, b, lvl):
        if not isinstance(a, dict):
            return {}
        if not isinstance(b, dict):
            return _deepcopy(a)

        result = {}
        for key, val in a.items():
            if key not in b:
                # key only in a
                result[key] = _deepcopy(val) if isinstance(val, dict) else val
            else:
                b_val = b[key]
                # both are dicts? recurse if allowed
                if isinstance(val, dict) and isinstance(b_val, dict):
                    if lvl == 0:
                        if val != b_val:
                            result[key] = _deepcopy(val)
                    else:
                        sub = _diff(val, b_val, lvl - 1 if lvl > 0 else -1)
                        if sub:
                            result[key] = sub
                else:
                    if val != b_val:
                        result[key] = _deepcopy(val) if isinstance(val, dict) else val
        return result

    return _diff(d1, d2, level)

