def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the labels to validate.

    Raises:
        ValidationError: if any of the keys and values do not match their
            respective regular expression. The error contains as message the list
            of all errors which occurred in the labels. Each element of the list is a
            dictionary with one key-value pair:
            - key: the label key or label value (or list element) for which an error occurred as string.
            - value: the error message.
    """
    import re
    errors = []

    # Regex patterns for label keys and values.
    key_pattern = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')
    value_pattern = re.compile(r'^[a-zA-Z0-9_.-]*$')

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if isinstance(key, bytes):
                try:
                    key_str = key.decode('utf-8')
                except Exception:
                    errors.append({str(key): 'expected string or bytes-like object'})
                    key_str = None
            else:
                key_str = key
            if key_str is not None and not key_pattern.match(key_str):
                errors.append({key_str: f"Label key '{key_str}' does not match the regex {key_pattern.pattern}"})

        # Validate value type
        if not isinstance(value, (str, bytes)):
            # If value is a non-string (e.g., list, bool), record its representation
            errors.append({repr(value): 'expected string or bytes-like object'})
        else:
            if isinstance(value, bytes):
                try:
                    value_str = value.decode('utf-8')
                except Exception:
                    errors.append({repr(value): 'expected string or bytes-like object'})
                    value_str = None
            else:
                value_str = value
            if value_str is not None and not value_pattern.match(value_str):
                errors.append({value_str: f"Label value '{value_str}' does not match the regex {value_pattern.pattern}"})

    if errors:
        raise ValidationError(errors)

