def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Creates a new dictionary from `manifest_dict` and replaces all non-list
    and non-dict values by `None`. If `first_level` is True, the values of
    identifying fields (``apiVersion``, ``kind``, ``metadata``) are copied
    from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    result = {}
    # Fields that identify a Kubernetes resource – preserve their values
    identifying_keys = {"apiVersion", "kind", "metadata"}

    for key, value in manifest_dict.items():
        # Preserve identifying fields at the first level
        if first_level and key in identifying_keys:
            result[key] = value
            continue

        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            # Assume a helper function exists to handle lists
            try:
                result[key] = generate_default_observer_schema_list(value)
            except NameError:
                # Fallback: keep a list of None entries with the same length
                result[key] = [None] * len(value)
        else:
            # Replace non-dict/list values with None
            result[key] = None

    return result

