def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """
    Recursively update the `last_applied_manifest` dictionary based on the fields
    defined in `observer_schema` and the values present in the Kubernetes API
    `response`. Only missing values in `last_applied_manifest` are added.
    """
    for field, schema in observer_schema.items():
        if field not in response:
            raise KeyError(f"Field {field!r} not present in the Kubernetes response")
        resp_value = response[field]

        # If the schema for this field is a dict, recurse into it
        if isinstance(schema, dict):
            if isinstance(resp_value, dict):
                # Ensure a nested dict exists in last_applied_manifest
                if field not in last_applied_manifest or not isinstance(last_applied_manifest[field], dict):
                    last_applied_manifest[field] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], schema, resp_value)
            else:
                # Schema expects a dict but got something else; just assign the value
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = resp_value

        # If the schema is a list, delegate to the list handling function
        elif isinstance(schema, list):
            if isinstance(resp_value, list):
                if field not in last_applied_manifest or not isinstance(last_applied_manifest[field], list):
                    last_applied_manifest[field] = []
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[field], schema, resp_value)
            else:
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = resp_value

        # For all other (primitive) schema types, simply copy if missing
        else:
            if field not in last_applied_manifest:
                last_applied_manifest[field] = resp_value
    return last_applied_manifest  # return to allow chaining, though modification is in-place

