def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dictionary")

    # Try to infer spec version from the 'type' field if requested
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Simple heuristic: look for 'v1' or 'v2' or name of provider
            if "v1" in type_val.lower() or "cloudformation" in type_val.lower():
                self.spec_version = 1
            elif "v2" in type_val.lower() or "terraform" in type_val.lower():
                self.spec_version = 2

    # Determine the version to test against
    spec_version = inventory.get("spec_version", self.spec_version)

    # Basic structural checks based on the spec version
    if spec_version == 1:
        # Version 1 requires a top‑level list of resources
        if "resources" not in inventory or not isinstance(inventory["resources"], list):
            raise ValueError("Spec v1 inventories must contain a 'resources' list")
    elif spec_version == 2:
        # Version 2 still requires a resources list but may also contain a metadata dict
        if "resources" not in inventory or not isinstance(inventory["resources"], list):
            raise ValueError("Spec v2 inventories must contain a 'resources' list")
        # Additional optional checks for v2
        if "metadata" in inventory and not isinstance(inventory["metadata"], dict):
            raise ValueError("Spec v2 'metadata' must be a dictionary if provided")
    else:
        raise ValueError(f"Unsupported spec version: {spec_version}")

    # If all checks pass, return True
    return True

