def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check all digests in manifest that are needed are present and used.
    Raises ValueError if any required digest is missing or if any digest in the
    manifest is not referenced in digests_used.
    """
    import json

    # Helper to recursively find all digest values in a parsed JSON object
    def _collect_digests(data):
        digests = set()
        if isinstance(data, dict):
            for key, value in data.items():
                if key == "digest" and isinstance(value, str):
                    digests.add(value)
                else:
                    digests.update(_collect_digests(value))
        elif isinstance(data, list):
            for item in data:
                digests.update(_collect_digests(item))
        return digests

    # Gather all digests present in the provided manifest files
    present_digests = set()
    for mf in manifest_files:
        try:
            # If mf is a file path, open it; if it's already a parsed dict, use directly
            if isinstance(mf, str):
                with open(mf, "r", encoding="utf-8") as fp:
                    content = json.load(fp)
            else:
                content = mf
        except Exception as exc:
            raise RuntimeError(f"Failed to read or parse manifest {mf}: {exc}") from exc

        present_digests.update(_collect_digests(content))

    # Convert digests_used to a set for efficient comparison
    required_digests = set(digests_used)

    # Check for missing required digests
    missing = required_digests.difference(present_digests)
    if missing:
        raise ValueError(f"The following required digests were not found in any manifest: {sorted(missing)}")

    # Optionally check for extraneous digests in manifests that are not used
    unused = present_digests.difference(required_digests)
    if unused:
        self.logger.warning(
            f"The following digests are present in the manifests but were not used: {sorted(unused)}"
        ) if hasattr(self, "logger") else None

    # If no exceptions were raised, the check passed
    return None

