def validate_as_prior_version(self, prior):
    """
    Validate that the supplied `prior` InventoryValidator represents an earlier
    snapshot of the same inventory. The function checks that:
      1. `prior` is an instance of the same class.
      2. The optional `version` attribute of the current object is newer than
         that of `prior` (if both attributes exist and are comparable).
      3. The optional `updated_at` timestamp of the current object is later
         than that of `prior` (if both attributes exist and are comparable).
      4. For the first attribute among ("items", "data", "inventory", "records")
         that contains a dictionary, every key/value pair in `prior` is present
         in the current object's dictionary, and numeric values have not
         decreased.
    On success, `True` is returned.  Any inconsistency raises a
    ValueError or TypeError where appropriate.
    """
    # 1. Instance type check
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"prior must be an instance of {type(self).__name__} not {type(prior).__name__}"
        )

    # 2. Version attribute comparison
    curr_version = getattr(self, "version", None)
    prior_version = getattr(prior, "version", None)
    if curr_version is not None and prior_version is not None:
        try:
            if curr_version <= prior_version:
                raise ValueError(
                    f"Current version ({curr_version}) must be greater than prior version ({prior_version})"
                )
        except TypeError:
            # If version objects are not directly comparable, ignore the check
            pass

    # 3. Timestamp comparison
    curr_ts = getattr(self, "updated_at", None)
    prior_ts = getattr(prior, "updated_at", None)
    if curr_ts is not None and prior_ts is not None:
        try:
            if curr_ts <= prior_ts:
                raise ValueError(
                    f"Current updated_at ({curr_ts}) must be later than prior updated_at ({prior_ts})"
                )
        except TypeError:
            # If timestamps cannot be compared, ignore the check
            pass

    # 4. Data consistency check
    data_attrs = ("items", "data", "inventory", "records")
    for attr_name in data_attrs:
        curr_data = getattr(self, attr_name, None)
        prior_data = getattr(prior, attr_name, None)
        if isinstance(curr_data, dict) and isinstance(prior_data, dict):
            # Ensure every key from prior exists in current
            for key, prior_val in prior_data.items():
                if key not in curr_data:
                    raise ValueError(
                        f"Key {key!r} from prior inventory missing in current inventory"
                    )
                curr_val = curr_data[key]
                # For numeric values, ensure they have not decreased
                if isinstance(curr_val, (int, float)) and isinstance(prior_val, (int, float)):
                    if curr_val < prior_val:
                        raise ValueError(
                            f"Current value for {key!r} ({curr_val}) is less than prior value ({prior_val})"
                        )
            # Successful validation on the first found data attribute
            break

    return True

