def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for a given
    version in inventory.

    Inventory can be either:
    - a list of items, each item being a dict with keys 'version',
      'logical_path', and 'content_file', or a tuple/list where these
      attributes are in the 0th, 1st, and 2nd positions respectively;
    - a dict mapping a version (numeric or string) to an iterable of
      items in the same format as above.

    Returns:
        dict: logical_path_in_state -> set(content_files)
    """
    def _as_int(val):
        try:
            return int(val)
        except Exception:
            return val

    def _greater(v1, v2):
        i1, i2 = _as_int(v1), _as_int(v2)
        try:
            return i1 > i2
        except Exception:
            return str(v1) > str(v2)

    # normalise inventory to a flat list of (ver, logical_path, content_file)
    entries = []
    if isinstance(inventory, dict):
        # dict mapping version -> iterable of items
        for v, it in inventory.items():
            if not isinstance(it, (list, tuple)):
                continue
            for entry in it:
                if isinstance(entry, dict):
                    logical_path = entry.get("logical_path")
                    content_file = entry.get("content_file")
                else:
                    if len(entry) >= 3:
                        logical_path, content_file = entry[1], entry[2]
                    else:
                        continue
                if logical_path is None or content_file is None:
                    continue
                entries.append((v, logical_path, content_file))
    else:
        # assume a single iterable of items
        for entry in inventory:
            if isinstance(entry, dict):
                v = entry.get("version")
                logical_path = entry.get("logical_path")
                content_file = entry.get("content_file")
            else:
                if len(entry) >= 3:
                    v, logical_path, content_file = entry[0], entry[1], entry[2]
                else:
                    continue
            if logical_path is None or content_file is None:
                continue
            entries.append((v, logical_path, content_file))

    # Build mapping for the requested version, including duplicate files
    # found in later versions that refer to the same logical path.
    mapping = {}
    for v, logical_path, content_file in entries:
        if v == version:
            mapping.setdefault(logical_path, set()).add(content_file)

    for v, logical_path, content_file in entries:
        if logical_path in mapping and _greater(v, version):
            mapping[logical_path].add(content_file)

    return mapping

