def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Track visited objects to avoid infinite recursion for circular references
    visited = set()

    def _render(obj, lvl):
        if id(obj) in visited:
            return "<<<circular>>>"
        visited.add(id(obj))

        if isinstance(obj, dict):
            items = []
            for k, v in obj.items():
                items.append(f"{_render(k, lvl+1)}: {_render(v, lvl+1)}")
            return "{" + ", ".join(items) + "}"
        if isinstance(obj, list):
            items = [_render(v, lvl+1) for v in obj]
            return "[" + ", ".join(items) + "]"
        if isinstance(obj, tuple):
            items = [_render(v, lvl+1) for v in obj]
            return "(" + ", ".join(items) + ("," if len(items) == 1 else "") + ")"
        if isinstance(obj, set):
            items = [_render(v, lvl+1) for v in obj]
            return "{" + ", ".join(items) + "}"
        if hasattr(obj, "__dict__"):
            attrs = []
            for key, val in vars(obj).items():
                attrs.append(f"{key}={_render(val, lvl+1)}")
            if debug:
                classname = obj.__class__.__name__
                return f"{classname}({', '.join(attrs)})"
            else:
                return f"{', '.join(attrs)}"
        return repr(obj)

    return _render(self, indent)

