def render(pieces, style):
    """
    Render the given version pieces into the requested style.

    The function accepts `pieces` either as a mapping with keys
    'major', 'minor', 'patch', 'prerelease', and optionally
    'build' (alternate spellings 'build_meta' or 'buildMetadata')
    or as an ordered sequence where the first three items are
    major, minor, and patch. The `style` argument selects the
    formatting scheme:

        * 'semver'   - standard semantic‑version string
        * 'plain'    - components joined by '.'
        * 'human'    - major.minor.patch only (prerelease and build omitted)
        * any other   - string representation of `pieces` (fallback)

    Returns
    -------
    str
        The rendered version string.
    """
    # Normalize mapping keys if pieces is a dict
    if isinstance(pieces, dict):
        major = pieces.get('major')
        minor = pieces.get('minor')
        patch = pieces.get('patch')
        prerelease = pieces.get('prerelease')
        build = pieces.get('build') or pieces.get('build_meta') or pieces.get('buildMetadata')
    else:
        # Assume an ordered sequence: major, minor, patch, [prerelease], [build]
        try:
            major, minor, patch = pieces[0], pieces[1], pieces[2]
        except Exception:
            major = minor = patch = None
        prerelease = pieces[3] if len(pieces) > 3 else None
        build = pieces[4] if len(pieces) > 4 else None

    if style == 'semver':
        if major is None or minor is None or patch is None:
            raise ValueError("Missing major, minor or patch components for semver style")
        base = f"{major}.{minor}.{patch}"
        if prerelease:
            base += f"-{prerelease}"
        if build:
            base += f"+{build}"
        return base
    elif style == 'plain':
        comps = [str(major), str(minor), str(patch)]
        if prerelease:
            comps.append(str(prerelease))
        if build:
            comps.append(str(build))
        return '.'.join(comp for comp in comps if comp is not None)
    elif style == 'human':
        if major is None or minor is None or patch is None:
            return str(pieces)
        return f"{major}.{minor}.{patch}"
    else:
        # Fallback: for mapping format as key=value, otherwise str
        if isinstance(pieces, dict):
            return ', '.join(f"{k}={v}" for k, v in pieces.items())
        return str(pieces)

