def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Turn commands into a list suitable for subprocess.run
    if isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    elif isinstance(commands, str):
        # Assume a single string command (no shell)
        cmd_list = [commands]
    else:
        raise TypeError(f"commands must be str, list or tuple, got {type(commands).__name__}")

    # Append arguments if they are provided
    if args is not None:
        if isinstance(args, (list, tuple)):
            cmd_list += list(args)
        elif isinstance(args, str):
            cmd_list.append(args)
        else:
            raise TypeError(f"args must be str, list or tuple, got {type(args).__name__}")

    if verbose:
        print(f"Running command: {' '.join(cmd_list)}")
        if cwd:
            print(f"  CWD: {cwd}")

    # Execute the command
    result = subprocess.run(
        cmd_list,
        cwd=cwd,
        env=env,
        capture_output=True,
        text=True,
        check=False
    )

    stdout = result.stdout
    stderr = '' if hide_stderr else result.stderr
    returncode = result.returncode

    if verbose:
        print(f"Return code: {returncode}")
        if not hide_stderr:
            print(f"stderr:\n{stderr}")

    return stdout, returncode, stderr

