def find_path_type(path):
    os = __import__('os')
    if not os.path.exists(path):
        return f'path does not exist: {path}'
    if os.path.isfile(path):
        return 'file'
    if os.path.isdir(path):
        # Search for namaste files named like '0=*'
        namaste_files = [f for f in os.listdir(path) if f.startswith('0=')]
        if not namaste_files:
            return 'no namaste file found'
        # Analyse the first found namaste file
        fpath = os.path.join(path, namaste_files[0])
        try:
            with open(fpath, 'r', encoding='utf-8') as ff:
                first_line = ff.readline().strip().lower()
        except Exception as e:
            return f'error reading namaste file {namaste_files[0]}: {e}'
        # Heuristics to distinguish root vs object
        if 'root' in first_line:
            return 'root'
        if 'object' in first_line:
            return 'object'
        # If we cannot decide, return the content as an explanatory message
        return f'unknown namaste content: {first_line}'
    return f'unknown path type: {path}'

