def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq_str = str(frequency).strip()
    if freq_str.lower() == "always":
        return None

    # Regular expression to capture the numeric part and the unit
    import re
    pattern = r'^(\d+(\.\d+)?)\s*([a-zA-Z]+)$'
    match = re.match(pattern, freq_str)
    if not match:
        raise ValueError(f"Frequency '{frequency}' is not in a recognized format.")

    value_str, _, unit = match.groups()
    try:
        value = float(value_str)
        # For now, we only accept integer quantities for timedelta
        if not value.is_integer():
            raise ValueError
        value = int(value)
    except ValueError:
        raise ValueError(f"Frequency value '{value_str}' is not a valid number.")

    unit = unit.lower()
    kwargs = {}
    if unit in ("second", "seconds"):
        kwargs["seconds"] = value
    elif unit in ("minute", "minutes"):
        kwargs["seconds"] = value * 60
    elif unit in ("hour", "hours"):
        kwargs["seconds"] = value * 3600
    elif unit in ("day", "days"):
        kwargs["days"] = value
    elif unit in ("week", "weeks"):
        kwargs["weeks"] = value
    else:
        raise ValueError(f"Unrecognized time unit '{unit}' in frequency '{frequency}'.")
    return datetime.timedelta(**kwargs)

