def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    if matcher is None or matcher == "":
        raise ValueError("matcher must be a non-empty string")
    # Split on the first ':' to separate the variable name from an optional default
    if ":" in matcher:
        var_name, default = matcher.split(":", 1)
    else:
        var_name, default = matcher, None
    var_name = var_name.strip()
    default = default.strip() if default is not None else None

    value = os.getenv(var_name)
    if value is None:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{var_name}' not found and no default provided.")
    return value

