def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise ValueError("seq cannot be None")

    # Helper to determine whether an object is a "native" sequence.
    # We consider built‑in sequence types (list, tuple, set variants, bytearray, memoryview)
    # and NumPy arrays/matrices if NumPy is available.
    native_seq_types = (list, tuple, set, frozenset, bytearray, memoryview)
    seq_type = type(seq)

    try:
        import numpy as _np
        if isinstance(seq, (_np.ndarray, _np.matrix)):
            return seq, seq_type
    except Exception:
        # NumPy is not available; ignore.
        pass

    if isinstance(seq, native_seq_types):
        return seq, seq_type

    # For all other iterable or generic objects, convert to a list.
    # If bufsize is specified, chunk the iterable into buffers before
    # converting to a list to avoid large memory consumption for generators.
    if bufsize is None:
        seq = list(seq)
    else:
        # Convert in chunks of `bufsize`
        seq = []
        it = iter(seq)
        while True:
            chunk = list()
            try:
                for _ in range(bufsize):
                    chunk.append(next(it))
            except StopIteration:
                seq.extend(chunk)
                break
            seq.extend(chunk)

    return seq, type(seq)

