def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        # Dynamically import urllib.request to avoid top-level import statements
        urllib_req = __import__('urllib.request')
        req = urllib_req.Request(url, method='HEAD')
        with urllib_req.urlopen(req) as response:
            # getheader is available in older Python versions; fall back to get_content_type
            header = response.headers.get('Content-Type')
            if header:
                return header.split(';', 1)[0].strip()
            else:
                # Fallback to Message object
                info = response.info()
                return info.get_content_type()
    except Exception:
        return None

