def parse_diaspora_webfinger(document: str) -> Dict:
    result = {}
    document = document.strip()
    if not document:
        return result
    # Simple JSON detection
    if document[0] == '{' or document[0] == '[':
        try:
            # Eval is used as a light‑weight JSON parser; restrict builtins for safety
            obj = eval(document, {"__builtins__": {}})
            if isinstance(obj, dict):
                result = obj
            else:
                result = {"data": obj}
        except Exception:
            result = {}
    else:
        # XRD parsing
        subject = None
        links = {}
        # Extract <Subject> if present
        sub_start = document.find('<Subject>')
        if sub_start != -1:
            sub_end = document.find('</Subject>', sub_start)
            if sub_end != -1:
                subject = document[sub_start + 9 : sub_end].strip()
                if subject:
                    result['subject'] = subject
        # Find all <Link ...> tags
        idx = 0
        while True:
            link_start = document.find('<Link', idx)
            if link_start == -1:
                break
            link_end = document.find('>', link_start)
            if link_end == -1:
                break
            link_tag = document[link_start:link_end + 1]
            # Extract rel attribute
            rel = None
            href = None
            rel_idx = link_tag.find('rel="')
            if rel_idx != -1:
                rel_start = rel_idx + 5
                rel_end = link_tag.find('"', rel_start)
                if rel_end != -1:
                    rel = link_tag[rel_start:rel_end]
            href_idx = link_tag.find('href="')
            if href_idx != -1:
                href_start = href_idx + 6
                href_end = link_tag.find('"', href_start)
                if href_end != -1:
                    href = link_tag[href_start:href_end]
            if rel and href:
                # Allow multiple links with same rel
                if rel in links:
                    if isinstance(links[rel], list):
                        links[rel].append(href)
                    else:
                        links[rel] = [links[rel], href]
                else:
                    links[rel] = href
            idx = link_end + 1
        if links:
            result['links'] = links
    return result

