def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file names found in the specified directories.
    If spec_option is provided, only files matching the option are returned.
    The option can be a simple substring or a shell-style glob pattern.
    """
    import os
    import fnmatch

    if not isinstance(settings_dirs, (list, tuple)):
        settings_dirs = [settings_dirs]

    files = set()
    for base_dir in settings_dirs:
        if not os.path.isdir(base_dir):
            continue
        for root, _, filenames in os.walk(base_dir):
            for name in filenames:
                if spec_option:
                    # Try glob matching first, then substring
                    if fnmatch.fnmatch(name, spec_option):
                        files.add(os.path.join(root, name))
                    elif spec_option in name:
                        files.add(os.path.join(root, name))
                else:
                    files.add(os.path.join(root, name))
    return sorted(files)

