def ansible_config_manager(cls):
    """Gets the ansible config manager."""
    # Determine the location of the ansible.cfg file
    import os
    import configparser

    config_file = os.getenv('ANSIBLE_CONFIG')
    if not config_file:
        # Search in the current working directory and the user's home directory
        for directory in (os.getcwd(), os.path.expanduser("~")):
            potential = os.path.join(directory, "ansible.cfg")
            if os.path.isfile(potential):
                config_file = potential
                break

    # If no config file is found, return an empty ConfigParser instance
    if not config_file:
        return configparser.ConfigParser()

    # Load and return the configuration manager
    cfg = configparser.ConfigParser()
    cfg.read(config_file)
    return cfg

