def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _merge_dict(dest, src):
        for key, val in src.items():
            if key in dest and isinstance(dest[key], dict) and isinstance(val, dict):
                _merge_dict(dest[key], val)
            else:
                dest[key] = val

    # Find include directive
    include = parser_dict.get('include')
    if not include:
        return

    # Groups to include
    groups_to_include = include.get('groups', [])
    groups_definitions = parser_dict.get('_groups', {})

    # Merge each group definition into the parser dict
    for group_name in groups_to_include:
        group_dict = groups_definitions.get(group_name)
        if group_dict is None:
            continue
        _merge_dict(parser_dict, group_dict)

    # Clean up temporary keys
    parser_dict.pop('include', None)
    parser_dict.pop('_groups', None)

