def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    import inspect
    defaults = {}
    # Get defaults from function signature if available
    if hasattr(self, 'func') and callable(self.func):
        sig = inspect.signature(self.func)
        for name, param in sig.parameters.items():
            if param.default is not inspect.Parameter.empty:
                defaults[name] = param.default
    # Merge with any spec dict provided
    if hasattr(self, 'spec') and isinstance(self.spec, dict):
        spec_defaults = self.spec.get('defaults')
        if isinstance(spec_defaults, dict):
            defaults.update(spec_defaults)
    # Override with instance attributes that match parameter names
    for name in list(defaults):
        if hasattr(self, name):
            defaults[name] = getattr(self, name)
    return defaults

