def get_silent_args(self, args):
    """
    Return the names of arguments that are considered silenced.

    Arguments that have a None value are treated as silenced.  The function accepts either
    a dictionary (common for keyword arguments) or an iterable of key/value pairs
    (e.g. a list of tuples).  In all other cases the function returns an empty list.
    """
    silent_names = []

    # Dictionary of keyword arguments
    if isinstance(args, dict):
        for key, value in args.items():
            if value is None:
                silent_names.append(key)
        return silent_names

    # Iterable of key/value tuples, like [(k, v), (k, v), ...]
    try:
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
                if value is None:
                    silent_names.append(key)
    except TypeError:
        # args is not iterable
        pass

    return silent_names

