def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # `self._choices` should map argument names to an iterable of allowed values.
    choices_map = getattr(self, "_choices", {})
    errors = []

    for arg_name, allowed in choices_map.items():
        # Only validate if the argument was actually provided.
        if arg_name in args:
            val = args[arg_name]
            if val not in allowed:
                errors.append(
