def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra_vars``.
    ``extra_vars`` can be None, a list of strings in the form ``key=value``,
    or dictionaries. String values that look like Python literals are parsed
    with ``ast.literal_eval``; otherwise they are treated as strings.
    Duplicate keys are overwritten by later entries.
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")
    if not extra_vars:
        return vars_dict

    import ast
    for item in extra_vars:
        if isinstance(item, dict):
            vars_dict.update(item)
        elif isinstance(item, str) and '=' in item:
            key, value = item.split('=', 1)
            try:
                parsed_value = ast.literal_eval(value)
            except Exception:
                parsed_value = value
            vars_dict[key] = parsed_value
        else:
            # Skip malformed items
            continue
    return vars_dict

